import whisper
import json
import re

# Filler definitions
SINGLE_WORDS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "basically", "well", "okay"
}

PHRASES = [
    "you know",
    "i mean",
    "kind of",
    "i guess"
]

def normalize_word(word):
    # Keep only alphanumeric
    return "".join(c for c in word if c.isalnum()).lower()

def detect_fillers(audio_path, output_json_path, internal_json_path):
    print(f"Loading model...")
    model = whisper.load_model("tiny")

    print(f"Transcribing {audio_path}...")
    result = model.transcribe(audio_path, word_timestamps=True, language="en")

    # Flatten all words into a list
    all_words = []
    for segment in result["segments"]:
        if "words" in segment:
            for w in segment["words"]:
                all_words.append({
                    "word": w["word"],
                    "clean": normalize_word(w["word"]),
                    "start": w["start"],
                    "end": w["end"]
                })

    detected = []

    # 1. Detect single words
    for i, w in enumerate(all_words):
        if w["clean"] in SINGLE_WORDS:
            detected.append({
                "word": w["word"].strip(), # Keep original casing/punctuation for display if needed, or normalized? User example shows "um", "like". I'll use the match key for consistency with user list if possible, or just the word found. User example: "um".
                # Actually user example keys are "um", "like", "you know". 
                # I should probably use the "canonical" form from the user's list for the "word" field?
                # User example: {"word": "um", ...}
                # If the transcript has "Um,", I should probably output "um" or "Um". 
                # I'll output the normalized matched word from the user's list to be safe and clean.
                "canonical": w["clean"], 
                "start": w["start"],
                "end": w["end"]
            })

    # 2. Detect phrases
    # Naive search for phrases
    for phrase in PHRASES:
        phrase_parts = phrase.split()
        n = len(phrase_parts)

        for i in range(len(all_words) - n + 1):
            # Check if n consecutive words match the phrase parts
            match = True
            for k in range(n):
                if all_words[i+k]["clean"] != normalize_word(phrase_parts[k]):
                    match = False
                    break

            if match:
                # Found a phrase
                start_time = all_words[i]["start"]
                end_time = all_words[i+n-1]["end"]
                detected.append({
                    "canonical": phrase,
                    "start": start_time,
                    "end": end_time
                })

    # Sort by timestamp
    detected.sort(key=lambda x: x["start"])

    # Filter duplicates? 
    # If "you know" is detected, "you" and "know" shouldn't be detected as single words if they were in the single word list.
    # None of the phrases contain words from the single word list (except maybe "i guess" -> "i" not in list).
    # "like" is in single list. "kind of" -> "kind", "of".
    # So overlap isn't a huge issue with this specific list.

    # Format for user
    user_output = []
    for d in detected:
        user_output.append({
            "word": d["canonical"], # Using the canonical form (e.g. "you know")
            "timestamp": d["start"]
        })

    # Format for internal use (includes end time)
    internal_output = []
    for d in detected:
        internal_output.append({
            "word": d["canonical"],
            "start": d["start"],
            "end": d["end"]
        })

    print(f"Found {len(detected)} filler words/phrases.")

    with open(output_json_path, "w") as f:
        json.dump(user_output, f, indent=2)

    with open(internal_json_path, "w") as f:
        json.dump(internal_output, f, indent=2)

if __name__ == "__main__":
    detect_fillers("/root/input.mp4", "/root/annotations.json", "/root/clips_info.json")

